#!/bin/bash
# Rebuilds ../pele.js from the pinned npm packages. See README.md in this folder.
# Usage: build.sh
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
out="$here/../pele.js"

stage=$(mktemp -d)
trap 'rm -rf "$stage"' EXIT
cp "$here/worker.js" "$here/budget.js" "$here/svg.js" "$here/fonts.js" "$here/package.json" "$here/package-lock.json" "$stage/"
(cd "$stage" && npm ci --no-audit --no-fund --ignore-scripts)
# pele's MIT notice travels beside the bundle. @resvg/resvg-wasm ships no LICENSE file, so LICENSE.resvg-wasm is kept by hand.
cp "$stage/node_modules/pele/LICENSE" "$here/LICENSE.pele"

# The fonts fonts.js names, with each package's OFL text, go beside the bundle in fonts/.
rm -rf "$here/fonts"
mkdir "$here/fonts"
(cd "$stage" && node --input-type=module -e "
import { SOURCES } from './fonts.js'
for (const { file, from } of SOURCES) console.log(from + ' ' + file)
") | while read -r from file; do
  cp "$stage/node_modules/$from" "$here/fonts/$file"
  package=$(echo "$from" | cut -d/ -f1-2)
  cp "$stage/node_modules/$package/LICENSE_FONT" "$here/fonts/OFL.$(basename "$package").txt"
done

version=$(node -p "require('$stage/node_modules/pele/package.json').version")
resvg=$(node -p "require('$stage/node_modules/@resvg/resvg-wasm/package.json').version")
(cd "$stage" && node node_modules/esbuild/bin/esbuild worker.js --bundle --platform=node --format=esm --minify --loader:.wasm=binary \
  --banner:js="// Generated by extensions/prism/core/vendor/pele/build.sh from pele $version and @resvg/resvg-wasm $resvg. Do not edit." \
  --outfile="$out")

echo "pele.js: $(du -h "$out" | cut -f1), pele $version, @resvg/resvg-wasm $resvg; fonts/: $(du -sh "$here/fonts" | cut -f1)"
